// Resume a falha que o n8n avisou (Error Trigger) em poucos campos e monta o aviso do Telegram.
// Vale para falha no meio de um workflow (execution) e para falha ao ligar um gatilho (trigger).
const dados = $('Quando algo falhar').first().json || {};
const execucao = dados.execution || {};
const gatilho = dados.trigger || {};
const wf = dados.workflow || {};
const erro = execucao.error || gatilho.error || {};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corta = (s, n) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};
const nome = corta(wf.name || 'Workflow sem nome', 120);
const no = corta(execucao.lastNodeExecuted || erro.node?.name || '', 120);
const mensagem = corta(erro.message || erro.description || 'erro sem mensagem', 300);
const link = /^https:\/\/[^\s"<>]+$/.test(String(execucao.url || '')) ? execucao.url : '';

// Uma dica curta para os erros mais comuns (o dono não é técnico).
let dica = '';
if (/\b401\b|unauthori[sz]ed|invalid_grant|expired|expirad|reconnect|reconect/i.test(mensagem)) {
  dica = 'Parece que uma conexão venceu: no n8n, abra Credentials, escolha a conexão desse serviço e clique em Reconnect.';
} else if (/\b429\b|quota|rate.?limit|resource.?exhausted|too many requests/i.test(mensagem)) {
  dica = 'Limite de uso do serviço gratuito: costuma voltar sozinho em algumas horas.';
} else if (/timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|socket hang up|\b50[234]\b/i.test(mensagem)) {
  dica = 'Instabilidade na internet ou no serviço: costuma passar sozinha na próxima rodada.';
}

const linhas = ['⚠️ <b>Kira: uma automação falhou</b>', `<b>${esc(nome)}</b>`];
if (no) linhas.push(`Onde: <i>${esc(no)}</i>`);
linhas.push(`Erro: ${esc(mensagem)}`);
if (dica) linhas.push(`💡 ${esc(dica)}`);
if (link) linhas.push(`<a href="${esc(link)}">Abrir a execução no n8n</a>`);
linhas.push('<i>Se ela falhar de novo hoje, eu só anoto, sem novo aviso. O resumo da semana chega na segunda.</i>');

return [
  {
    json: {
      workflow_id: String(wf.id ?? ''),
      workflow: nome,
      no,
      erro: mensagem,
      execucao_id: String(execucao.id ?? ''),
      modo: String(execucao.mode || gatilho.mode || ''),
      html: linhas.join('\n'),
    },
  },
];

// Monta o resumo semanal da saúde da Kira (HTML do Telegram): conexões, falhas dos últimos 7 dias, base de pedidos,
// último backup e quando reconectar o LinkedIn. Cada verificação que falhar vira um item de "Para olhar",
// sem derrubar o resto.
const cfg = $('Configuração da saúde').first().json;
const fuso = cfg.fuso_horario || 'America/Sao_Paulo';
const agora = new Date(cfg.agora || Date.now());
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corta = (s, n) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};
const resposta = (no) => {
  try {
    return $(no).first()?.json ?? {};
  } catch (e) {
    return { error: { message: 'não rodou' } };
  }
};
const falhou = (r) => Boolean(r.error);
const motivo = (r) => {
  const m = corta(r.error?.message ?? r.error?.description ?? (typeof r.error === 'string' ? r.error : ''), 100) || 'sem resposta';
  return /\b401\b|unauthori[sz]ed|invalid_grant|expired/i.test(m) ? `${m} (reconecte no n8n: Credentials → Reconnect)` : m;
};
const valida = (iso) => {
  const d = new Date(iso);
  return isNaN(d) ? null : d;
};
const diaMes = (d) => d.toLocaleDateString('pt-BR', { timeZone: fuso, day: '2-digit', month: '2-digit' });
const diaHora = (d) =>
  d.toLocaleString('pt-BR', { timeZone: fuso, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).replace(', ', ' às ');
const diasDesde = (d) => (agora - d) / 86400000;
const paraOlhar = [];
// Só entram no resumo os serviços da lista "servicos" da configuração.
const usados = String(cfg.servicos ?? 'outlook, drive, gemini, powerbi, linkedin, pedidos').toLowerCase().split(/[\s,;]+/).filter(Boolean);
const usa = (servico) => usados.includes(servico);

// Conexões: uma leitura simples em cada serviço.
const conexoes = [
  ['Outlook', 'Outlook', 'outlook'],
  ['Google Drive', 'Google Drive e último backup', 'drive'],
  ['Gemini', 'Gemini', 'gemini'],
  ['Power BI', 'Power BI', 'powerbi'],
  ['LinkedIn', 'LinkedIn', 'linkedin'],
].filter((c) => usa(c[2]));
let conexoesOk = 0;
const marcas = conexoes.map(([rotulo, no]) => {
  const r = resposta(no);
  if (falhou(r)) {
    paraOlhar.push(`${rotulo}: ${motivo(r)}`);
    return `⚠️ ${rotulo}`;
  }
  conexoesOk += 1;
  return `✅ ${rotulo}`;
});

// Falhas anotadas pelo aviso de falhas (execuções de teste não contam).
let falhas = null;
try {
  const linhas = $('Falhas da semana').all().map((i) => i.json);
  if (!linhas.some((r) => r && r.error)) falhas = linhas.filter((r) => r && r.id !== undefined && r.modo !== 'manual');
} catch (e) {}
const grupos = new Map();
for (const f of falhas ?? []) {
  const chave = f.workflow || f.workflow_id || 'Workflow sem nome';
  const g = grupos.get(chave) ?? { nome: chave, total: 0, ultima: '', no: '' };
  g.total += 1;
  if (String(f.createdAt ?? '') >= g.ultima) {
    g.ultima = String(f.createdAt ?? '');
    g.no = f.no || '';
  }
  grupos.set(chave, g);
}
const listaGrupos = [...grupos.values()].sort((a, b) => b.total - a.total || b.ultima.localeCompare(a.ultima));
const MAX = 6;
const linhaGrupo = (g) => {
  const quando = valida(g.ultima);
  const detalhes = [quando ? `última ${diaHora(quando)}` : '', g.no ? `em <i>${esc(corta(g.no, 50))}</i>` : ''].filter(Boolean).join(', ');
  return `• ${esc(corta(g.nome, 60))}: ${g.total}${detalhes ? ` (${detalhes})` : ''}`;
};

// Base de pedidos: o arquivo que a sincronização grava no OneDrive.
const base = usa('pedidos') ? resposta('Base de pedidos (OneDrive)') : {};
const MAX_BASE = Number(cfg.base_max_dias) || 4;
let linhaBase = '';
let baseOk = usa('pedidos') ? false : null;
const dataBase = valida(base.lastModifiedDateTime);
if (!usa('pedidos')) {
  // sem a base de pedidos, a linha não aparece
} else if (falhou(base)) {
  linhaBase = '⚠️ não consegui conferir';
  paraOlhar.push(`Base de pedidos: ${motivo(base)}`);
} else if (!dataBase) {
  linhaBase = '⚠️ arquivo não encontrado';
  paraOlhar.push('Base de pedidos: o arquivo da base não apareceu no OneDrive');
} else if (diasDesde(dataBase) > MAX_BASE) {
  linhaBase = `⚠️ parada desde ${diaHora(dataBase)}`;
  paraOlhar.push(`Base de pedidos: sem atualização há ${Math.floor(diasDesde(dataBase))} dias`);
} else {
  baseOk = true;
  linhaBase = `✅ atualizada em ${diaHora(dataBase)}`;
}

// Último backup (a pasta do Google Drive).
const drive = usa('drive') ? resposta('Google Drive e último backup') : {};
const MAX_BACKUP = Number(cfg.backup_max_dias) || 8;
const ultimo = (drive.files ?? [])[0];
const dataBackup = valida(ultimo?.createdTime);
let linhaBackup = '';
let backupOk = usa('drive') ? false : null;
if (!usa('drive')) {
  // o backup fica no Google Drive: sem ele, a linha não aparece
} else if (falhou(drive)) linhaBackup = '⚠️ não consegui conferir';
else if (!dataBackup) {
  linhaBackup = '⚠️ nenhum backup ainda';
  paraOlhar.push('Backup: nenhum arquivo na pasta de backups');
} else {
  const kb = Math.round((Number(ultimo.size) || 0) / 1024);
  const tamanho = kb >= 1024 ? `${(kb / 1024).toFixed(1).replace('.', ',')} MB` : `${kb} KB`;
  backupOk = diasDesde(dataBackup) <= MAX_BACKUP;
  linhaBackup = `${backupOk ? '✅' : '⚠️'} ${diaHora(dataBackup)} (${tamanho})`;
  if (!backupOk) paraOlhar.push(`Backup: o último tem ${Math.floor(diasDesde(dataBackup))} dias`);
}

// LinkedIn: o acesso dura 60 dias e não renova sozinho.
let linhaLinkedin = '';
let faltamLinkedin = null;
// Conta em dias de calendário (data de hoje no fuso do dono contra a data do vencimento).
const conectado = valida(String(cfg.linkedin_conectado_em || '').slice(0, 10) + 'T12:00:00Z');
if (usa('linkedin') && cfg.linkedin_conectado_em && conectado) {
  const vence = new Date(conectado.getTime() + (Number(cfg.linkedin_validade_dias) || 60) * 86400000);
  const hoje = new Date(agora.toLocaleDateString('en-CA', { timeZone: fuso }) + 'T12:00:00Z');
  faltamLinkedin = Math.round((vence - hoje) / 86400000);
  if (faltamLinkedin < 0) {
    linhaLinkedin = `⚠️ a conexão venceu em ${diaMes(vence)}`;
    paraOlhar.push('LinkedIn: reconecte no n8n (Credentials → LinkedIn → Reconnect) e anote a nova data na Configuração da saúde');
  } else if (faltamLinkedin <= 10) {
    linhaLinkedin = `⚠️ reconectar até ${diaMes(vence)} (faltam ${faltamLinkedin} dias)`;
    paraOlhar.push('LinkedIn: reconecte no n8n (Credentials → LinkedIn → Reconnect) e anote a nova data na Configuração da saúde');
  } else linhaLinkedin = `reconectar até ${diaMes(vence)} (faltam ${faltamLinkedin} dias)`;
}

const partes = [`🩺 <b>Saúde da Kira</b> — semana até ${diaMes(agora)}`, '', `<b>Conexões:</b> ${marcas.join(' · ')}`, ''];
if (falhas === null) {
  partes.push('<b>Falhas nos últimos 7 dias:</b> ?');
  paraOlhar.push('Falhas: não consegui ler a tabela kira_saude');
} else if (!falhas.length) partes.push('<b>Falhas nos últimos 7 dias:</b> nenhuma 🎉');
else {
  partes.push(`<b>Falhas nos últimos 7 dias:</b> ${falhas.length}`);
  partes.push(listaGrupos.slice(0, MAX).map(linhaGrupo).join('\n') + (listaGrupos.length > MAX ? `\n…e mais ${listaGrupos.length - MAX}` : ''));
}
partes.push('');
if (linhaBase) partes.push(`<b>Base de pedidos:</b> ${linhaBase}`);
if (linhaBackup) partes.push(`<b>Último backup:</b> ${linhaBackup}`);
if (linhaLinkedin) partes.push(`<b>LinkedIn:</b> ${linhaLinkedin}`);
partes.push('');
if (paraOlhar.length) partes.push('👀 <b>Para olhar:</b>\n' + paraOlhar.map((p) => `• ${esc(p)}`).join('\n'));
else partes.push('Tudo certo por aqui. 💪');

const html = partes.join('\n').replace(/\n{3,}/g, '\n\n').trim();
const texto_simples = esc(html.replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&'));
return [
  {
    json: {
      html,
      texto_simples,
      contagens: {
        conexoes_ok: conexoesOk,
        conexoes_com_problema: conexoes.length - conexoesOk,
        falhas_7_dias: falhas === null ? null : falhas.length,
        workflows_com_falha: falhas === null ? null : listaGrupos.length,
        base_ok: baseOk,
        backup_ok: backupOk,
        linkedin_faltam_dias: faltamLinkedin,
        itens_para_olhar: paraOlhar.length,
      },
    },
  },
];
